//! 🗂️ Multi-target transform patches finish every original and unpublished-post lookup before commit.
use semio_s_artifact_draw_drawing_model::{DrawingTransform,layer_base_mut,snapshot::{DrawingSnapshot,lookup::original::{DrawingOriginalLookup,DrawingOriginalLayerAddress as Address}}};
use crate::{DrawingDiff,DrawingLayerPatch};
use protocol::{RetainedDiffPreflightAdvance,ApplyCapability};
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneRef,RetainedCloneBinding,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedCloneClose,retained_clone_grant_admits,close_retained_binding}};
use std::mem::{ManuallyDrop,size_of};
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"Drawing multi-transform original custody changed")}
fn bad()->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,"Drawing multi-transform requires distinct original and post targets")}
fn fixed(copy_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,depth:1,..Default::default()}}
fn metadata()->usize{2*size_of::<Address>()+2*size_of::<DrawingTransform>()+256}
fn nested(mut d:RetirementDemand)->Result<RetirementDemand,ValueError>{d.copy_bytes=d.copy_bytes.checked_add(metadata()).ok_or_else(invalid)?;d.depth=d.depth.checked_add(1).ok_or_else(invalid)?;Ok(d)}
fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-metadata(),maximum_depth:g.maximum_depth-1,..g}}
fn paid(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_items=p.copied_items.max(1);p.copied_bytes+=metadata();p}
fn count(d:&DrawingDiff)->Result<usize,ValueError>{if d.schema.is_some()||d.id.is_some()||d.title.is_some()||d.assets.is_some()||d.artboard.is_some(){return Err(bad())}let l=d.layers.as_ref().ok_or_else(bad)?;if !l.removed.is_empty()||!l.inserted.is_empty()||!l.moved.is_empty()||l.modified.len()<2{return Err(bad())}Ok(l.modified.len())}
fn id<'a>(d:RetainedCloneRef<'a,DrawingDiff>,i:usize)->RetainedCloneRef<'a,String>{d.project(3,|d|d.layers.as_ref().unwrap()).project(3,|l|&l.modified).project(i,move|l|&l[i]).project(0,|r|&r.id)}
fn transform(p:&DrawingLayerPatch)->Result<&DrawingTransform,ValueError>{if p.visible.is_some()||p.locked.is_some()||p.name.is_some()||p.opacity.is_some()||p.blend_mode.is_some()||p.fill_rule.is_some()||p.isolation.is_some()||p.fill.is_some()||p.stroke.is_some()||p.boolean_operation.is_some()||p.trace_params.is_some()||p.layer.is_some()||p.path_segments.is_some()||p.text_content.is_some()||p.text_size.is_some()||p.font_family.is_some()||p.image_key.is_some()||p.image_width.is_some()||p.image_height.is_some()||!p.shape_coordinates.is_empty(){return Err(bad())}let t=p.transform.as_ref().ok_or_else(bad)?;if ![t.x,t.y,t.scale_x,t.scale_y,t.shear,t.rotation].into_iter().all(f64::is_finite){return Err(bad())}Ok(t)}
/// 📋️ Only fixed paths are retained; original dynamic diff strings remain with their issuer.
pub struct DrawingRetainedTransformsApply{diff:Option<RetainedCloneBinding>,base:Option<RetainedCloneBinding>,original:DrawingOriginalLookup,post:DrawingOriginalLookup,paths:ManuallyDrop<Option<Vec<Address>>>,retirement:RetainedCloneClose,at:Option<Address>,index:usize,scan:usize,phase:u8,closing:bool}
impl Default for DrawingRetainedTransformsApply{fn default()->Self{Self{diff:None,base:None,original:Default::default(),post:Default::default(),paths:ManuallyDrop::new(None),retirement:Default::default(),at:None,index:0,scan:0,phase:0,closing:false}}}
impl DrawingRetainedTransformsApply{
 pub fn demand(&self,d:RetainedCloneRef<'_,DrawingDiff>,b:RetainedCloneRef<'_,DrawingSnapshot>,p:RetainedCloneRef<'_,DrawingSnapshot>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.phase>=7{return Err(invalid())}let n=count(d.get())?;if !d.check_binding(&self.diff)?{return Ok(fixed(d.binding_copy_bytes()))}if !b.check_binding(&self.base)?{return Ok(fixed(b.binding_copy_bytes()))}let inner=body.saturating_sub(metadata());Ok(match self.phase{0=>RetirementDemand{capacity_bytes:n.checked_mul(size_of::<Address>()).ok_or_else(invalid)?,..fixed(metadata())},1=>nested(self.original.demand(b,id(d,self.index),inner)?)?,2=>nested(self.post.demand(p,id(d,self.index),inner)?)?,3=>fixed(metadata()),4=>nested(self.original.close_demand(inner)?)?,5=>nested(self.post.close_demand(inner)?)?,6=>fixed(metadata()),_=>return Err(invalid())})}
 pub fn preflight(&mut self,d:RetainedCloneRef<'_,DrawingDiff>,b:RetainedCloneRef<'_,DrawingSnapshot>,post:RetainedCloneRef<'_,DrawingSnapshot>,body:usize,g:RetainedCloneGrant)->Result<RetainedDiffPreflightAdvance,ValueError>{let demand=self.demand(d,b,post,body)?;if !retained_clone_grant_admits(g,demand){return Ok(RetainedDiffPreflightAdvance::Progress(Default::default()))}if let Some(p)=d.bind(&mut self.diff,g)?{return Ok(RetainedDiffPreflightAdvance::Progress(p))}if let Some(p)=b.bind(&mut self.base,g)?{return Ok(RetainedDiffPreflightAdvance::Progress(p))}let n=count(d.get())?;let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()};let result=(||->Result<(),ValueError>{match self.phase{
  0=>{*self.paths=Some(Vec::new());self.phase=254;let r=self.paths.as_mut().unwrap().try_reserve_exact(n);p.retained_capacity_bytes=self.paths.as_ref().unwrap().capacity()*size_of::<Address>();if r.is_err()||!p.fits(g){return Err(invalid())}self.phase=1},
  1=>{transform(&d.get().layers.as_ref().unwrap().modified[self.index].patch)?;p=paid(self.original.advance(b,id(d,self.index),body.saturating_sub(metadata()),child(g))?.progress());if self.original.ready(){self.original.address()?.ok_or_else(bad)?;self.phase=2}},
  2=>{p=paid(self.post.advance(post,id(d,self.index),body.saturating_sub(metadata()),child(g))?.progress());if self.post.ready(){self.at=Some(self.post.address()?.ok_or_else(bad)?);self.scan=0;self.phase=3}},
  3=>{if self.scan<self.index{if self.paths.as_ref().unwrap()[self.scan]==self.at.ok_or_else(invalid)?{return Err(bad())}self.scan+=1}else{self.original.begin_close();self.post.begin_close();self.phase=4}},
  4=>{p=paid(self.original.close_step(child(g))?.progress());if self.original.terminal_is_empty(){self.phase=5}},5=>{p=paid(self.post.close_step(child(g))?.progress());if self.post.terminal_is_empty(){self.phase=6}},
  6=>{self.paths.as_mut().unwrap().push(self.at.take().ok_or_else(invalid)?);self.original=Default::default();self.post=Default::default();self.index+=1;if self.index==n{self.index=0;self.phase=7}else{self.phase=1}},_=>return Err(invalid())}Ok(())})();if let Err(e)=result{let mut q=e.retained_progress();q.copied_items=q.copied_items.max(p.copied_items);q.copied_bytes=q.copied_bytes.saturating_add(metadata()).max(p.copied_bytes);q.retained_capacity_bytes=q.retained_capacity_bytes.max(p.retained_capacity_bytes);return Err(e.with_retained_progress(q))}Ok(if self.phase==7{RetainedDiffPreflightAdvance::Ready(p,true)}else{RetainedDiffPreflightAdvance::Progress(p)})}
 pub fn commit_demand(&self,d:RetainedCloneRef<'_,DrawingDiff>,b:RetainedCloneRef<'_,DrawingSnapshot>,post:&DrawingSnapshot)->Result<RetirementDemand,ValueError>{if self.closing||self.phase!=7||!d.check_binding(&self.diff)?||!b.check_binding(&self.base)?{return Err(invalid())}let n=count(d.get())?;if self.index>=n||self.paths.as_ref().is_none_or(|p|p.len()!=n){return Err(invalid())}transform(&d.get().layers.as_ref().unwrap().modified[self.index].patch)?;self.paths.as_ref().unwrap()[self.index].node(post).ok_or_else(invalid)?;Ok(fixed(metadata()+2*size_of::<semio_s_artifact_draw_drawing_model::DrawingLayerNode>()))}
 pub fn commit(&mut self,d:RetainedCloneRef<'_,DrawingDiff>,b:RetainedCloneRef<'_,DrawingSnapshot>,post:&mut DrawingSnapshot,g:RetainedCloneGrant,_capability:ApplyCapability)->Result<RetainedCloneStep,ValueError>{let demand=self.commit_demand(d,b,post)?;if !retained_clone_grant_admits(g,demand){return Ok(RetainedCloneStep::Progress(Default::default()))}let t=transform(&d.get().layers.as_ref().unwrap().modified[self.index].patch)?;let node=self.paths.as_ref().unwrap()[self.index].node_mut(post).ok_or_else(invalid)?;layer_base_mut(node).transform=DrawingTransform{x:t.x,y:t.y,scale_x:t.scale_x,scale_y:t.scale_y,shear:t.shear,rotation:t.rotation};self.index+=1;let p=RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()};Ok(if self.index==count(d.get())?{self.phase=8;RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn begin_close(&mut self){self.closing=true;self.original.begin_close();self.post.begin_close();}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.original.terminal_is_empty(){return self.original.close_demand(body)}if !self.post.terminal_is_empty(){return self.post.close_demand(body)}if !self.retirement.is_empty()||self.paths.is_some(){return self.retirement.next_owner_demands::<Vec<Address>>(self.paths.is_some(),&None,body)}if self.diff.is_some(){return RetainedCloneBinding::close_demand(&self.diff,body)}RetainedCloneBinding::close_demand(&self.base,body)}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(invalid())}let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.original.terminal_is_empty(){return self.original.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.post.terminal_is_empty(){return self.post.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.retirement.is_empty(){return self.retirement.step_granted(g)}if let Some(s)=self.retirement.begin_granted(&mut self.paths,g)?{return Ok(s)}if self.diff.is_some(){return close_retained_binding(&mut self.diff,g).map(|s|RetainedCloneStep::Progress(s.progress()))}close_retained_binding(&mut self.base,g)}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.diff.is_none()&&self.base.is_none()&&self.original.terminal_is_empty()&&self.post.terminal_is_empty()&&self.paths.is_none()&&self.retirement.is_empty()}
}
impl Drop for DrawingRetainedTransformsApply{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Drawing multi-transform paths require explicit original close");}}
